<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$rows=$db->query("SELECT d.id,d.numero_demande,d.statut,d.date_demande,cr.libelle categorie,c.type_client,c.nom,c.prenom,c.raison_sociale,(SELECT COUNT(*) FROM offres_devis o WHERE o.demande_id=d.id) nb_offres FROM demandes_devis d JOIN clients c ON c.id=d.client_id JOIN categories_risque cr ON cr.id=d.categorie_id WHERE d.statut IN ('complete','comparee') ORDER BY d.date_demande DESC")->fetchAll();$title='Comparaisons';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Comparaisons tarifaires</h1><p class="text-secondary">Demandes prêtes pour le calcul multi-compagnies</p></div><a class="btn btn-outline-secondary" href="<?= APP_URL ?>/demandes/index.php">Demandes</a></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Demande</th><th>Client</th><th>Branche</th><th>Offres</th><th>Statut</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($rows as $r): $client=$r['type_client']==='entreprise'?$r['raison_sociale']:trim($r['prenom'].' '.$r['nom']);?><tr><td class="fw-semibold"><?= e($r['numero_demande']) ?></td><td><?= e($client) ?></td><td><?= e($r['categorie']) ?></td><td><?= (int)$r['nb_offres'] ?></td><td><?= e($r['statut']) ?></td><td class="text-end"><form class="d-inline" method="post" action="<?= APP_URL ?>/demandes/calculer.php"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-success"><?= $r['statut']==='comparee'?'Recalculer':'Calculer les offres' ?></button></form> <?php if($r['statut']==='comparee'): ?><a class="btn btn-sm btn-primary" href="<?= APP_URL ?>/demandes/comparateur.php?id=<?= (int)$r['id'] ?>">Comparer</a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-state">Aucune demande complète.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
